namespace ghidra.app.util.viewer.format.actions;

using ghidra.app.util;
using ghidra.app.util.viewer.field;
using ghidra.app.util.viewer.format;
using ghidra.util;
using docking;
using docking.action;
using docking.action;

/**
 * Action for adding SpacerFields to a FieldModel
 */
public class AddSpacerFieldAction : DockingAction {
	private FieldHeader panel;
	
    public AddSpacerFieldAction(string owner, FieldHeader panel) : base("Add Spacer Field", owner, false)
    {
        this.panel = panel;
        setPopupMenuData(new MenuData(new string[] {"Add Field", "Spacer"},"header a"));
        setEnabled(true);
		setHelpLocation(new HelpLocation(HelpTopics.CODE_BROWSER, "Add Field"));
    }
    /* @Override */
	public bool isEnabledForContext(ActionContext context) {
    	return context.getContextObject() is FieldHeaderLocation;
	}

    /**
     * Method called when the action is invoked.
     */
    /* @Override */
    public void actionPerformed(ActionContext context) {
    	FieldHeaderLocation loc = (FieldHeaderLocation) context.getContextObject();
        FieldFormatModel modelAtLocation = loc.getModel();
    	panel.setTabLock( true );
    	modelAtLocation.addFactory(new SpacerFieldFactory(), loc.getRow(), loc.getColumn());
    }

}

